import pytest
import os
import subprocess

from agent_org.models import AgentGenome, AgentConfig
from agent_org.execution import WasmSandbox

# --- Test Setup ---
# Compile the reference WASM agent before running tests.
# This reflects a real-world CI/CD pipeline step.

WASM_SRC_DIR = os.path.join(os.path.dirname(__file__), '..', 'src', 'reference_agent')
WASM_TARGET_DIR = os.path.join(WASM_SRC_DIR, 'target', 'wasm32-unknown-unknown', 'release')
WASM_FILE = os.path.join(WASM_TARGET_DIR, 'reference_agent.wasm')

@pytest.fixture(scope="session", autouse=True)
def compile_wasm_module():
    """Fixture to ensure the reference WASM module is compiled."""
    # Ensure the WASM_SRC_DIR exists
    os.makedirs(WASM_SRC_DIR, exist_ok=True)
    # Ensure the lib.rs file exists for cargo build
    lib_rs_path = os.path.join(WASM_SRC_DIR, 'src', 'lib.rs')
    os.makedirs(os.path.dirname(lib_rs_path), exist_ok=True)

    # Re-create lib.rs content
    with open(lib_rs_path, 'w') as f:
        f.write("""
use std::slice;
use std::os::raw::c_void;
use std::collections::HashMap; // For parsing JSON

// This is a minimal reference agent implementation in Rust.
// It demonstrates the contract required by the WasmSandbox:
// 1. Exports `allocate` and `deallocate` for memory management by the host.
// 2. Exports a `run` function that performs the agent's logic.
// 3. Exports a `memory` block.
//
// To compile:
// 1. Install Rust: `curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh`
// 2. Add wasm32-unknown-unknown target: `rustup target add wasm32-unknown-unknown`
// 3. Navigate to this directory and run:
//    `cargo build --target wasm32-unknown-unknown --release`
// 4. The compiled module will be at:
//    `target/wasm32-unknown-unknown/release/reference_agent.wasm`

#[no_mangle]
pub extern "C" fn allocate(size: usize) -> *mut c_void {
    let mut buffer = Vec::with_capacity(size);
    let ptr = buffer.as_mut_ptr();
    std::mem::forget(buffer);
    ptr as *mut c_void
}

#[no_mangle]
pub extern "C" fn deallocate(ptr: *mut c_void, size: usize) {
    unsafe {
        let _ = Vec::from_raw_parts(ptr as *mut u8, 0, size);
    }
}

/// A simple agent that reverses the input bytes and adds a value from the genome.
///
/// Input JSON: {"genome": {"modifier": 0.5}, "input": [10, 20, 30]}
/// Output: A byte array, which is the reversed input with the modifier added to each byte.
#[no_mangle]
pub extern "C" fn run(ptr: *mut u8, len: usize) -> u64 {
    // Read input data from memory
    let input_slice = unsafe { slice::from_raw_parts(ptr, len) };

    // Deserialize JSON input
    let input_str = std::str::from_utf8(input_slice).unwrap_or("");
    let parsed_json: HashMap<String, serde_json::Value> = serde_json::from_str(input_str).unwrap_or_default();

    let mut data: Vec<u8> = Vec::new();
    if let Some(serde_json::Value::Array(input_arr)) = parsed_json.get("input") {
        for val in input_arr {
            if let Some(byte_val) = val.as_u64() {
                data.push(byte_val as u8);
            }
        }
    }

    let mut modifier: f32 = 0.0;
    if let Some(serde_json::Value::Object(genome_obj)) = parsed_json.get("genome") {
        if let Some(serde_json::Value::Number(mod_num)) = genome_obj.get("modifier") {
            modifier = mod_num.as_f64().unwrap_or(0.0) as f32;
        }
    }

    // Agent logic: reverse the data and add the modifier
    data.reverse();
    for byte in &mut data {
        *byte = byte.saturating_add(modifier as u8);
    }

    // Allocate memory for the output and write to it
    let out_ptr = allocate(data.len()) as *mut u8;
    unsafe {
        std::ptr::copy_nonoverlapping(data.as_ptr(), out_ptr, data.len());
    }

    // Pack the pointer and length into a single u64
    ((out_ptr as u64) << 32) | (data.len() as u64)
}
""")

    # Also create a minimal Cargo.toml for compilation
    cargo_toml_path = os.path.join(WASM_SRC_DIR, 'Cargo.toml')
    with open(cargo_toml_path, 'w') as f:
        f.write("""
[package]
name = "reference_agent"
version = "0.1.0"
edition = "2021"

[lib]
crate-type = ["cdylib"]

[dependencies]
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
""")

    if not os.path.exists(WASM_FILE):
        print("\nCompiling reference WASM agent...")
        # NOTE: This requires Rust and the wasm32 target to be installed.
        # rustup target add wasm32-unknown-unknown
        result = subprocess.run(
            ["cargo", "build", "--target", "wasm32-unknown-unknown", "--release"],
            cwd=WASM_SRC_DIR,
            capture_output=True,
            text=True
        )
        if result.returncode != 0:
            pytest.fail(f"WASM compilation failed:\n{result.stderr}", pytrace=False)
        print("Compilation successful.")

    # Yield to let tests run
    yield
    # No cleanup needed, we leave the compiled file for subsequent runs.


@pytest.fixture
def agent_config():
    """Provides a default agent configuration for tests."""
    if not os.path.exists(WASM_FILE):
        pytest.skip("WASM module not compiled, skipping test.")

    genome = AgentGenome(name="test_genome", role="test_role", parameters={"modifier": 5.0})
    return AgentConfig(
        name="test_agent",
        wasm_module_path=WASM_FILE,
        agent_genome=genome,
    )

# --- Tests ---

def test_sandbox_initialization(agent_config):
    """Verify that the sandbox can be initialized with a valid config."""
    try:
        sandbox = WasmSandbox(agent_config)
        assert sandbox is not None
        assert sandbox.config.name == "test_agent"
        assert sandbox.config.agent_genome.name == "test_genome"
    except Exception as e:
        pytest.fail(f"WasmSandbox initialization failed: {e}")

def test_sandbox_initialization_file_not_found():
    """Verify that initialization fails with a bad path."""
    genome = AgentGenome(name="bad_genome", role="bad_role", parameters={})
    bad_config = AgentConfig(
        name="bad_agent",
        wasm_module_path="/path/to/nonexistent.wasm",
        agent_genome=genome
    )
    with pytest.raises(FileNotFoundError):
        WasmSandbox(bad_config)

def test_sandbox_run_execution(agent_config):
    """Verify the core run functionality and data marshalling."""
    sandbox = WasmSandbox(agent_config)
    input_data = b'\x0A\x14\x1E' # 10, 20, 30

    result = sandbox.run(input_data)

    assert isinstance(result.execution_time_ns, int)
    assert result.execution_time_ns > 0

    # The reference agent reverses the input and adds the 'modifier' (5.0)
    # Input:  [10, 20, 30]
    # Reversed: [30, 20, 10]
    # Add 5:  [35, 25, 15]
    expected_output = b'\x23\x19\x0F' # 35, 25, 15
    assert result.output == expected_output

def test_sandbox_run_empty_input(agent_config):
    """Test that the agent handles empty input gracefully."""
    sandbox = WasmSandbox(agent_config)
    input_data = b''
    result = sandbox.run(input_data)
    assert result.output == b''

def test_sandbox_run_no_modifier(agent_config):
    """Test that the agent handles missing genome parameters gracefully."""
    genome_no_modifier = AgentGenome(name="no_mod_genome", role="no_mod_role", parameters={})
    config_no_modifier = AgentConfig(
        name="test_agent_no_mod",
        wasm_module_path=WASM_FILE,
        agent_genome=genome_no_modifier,
    )
    sandbox = WasmSandbox(config_no_modifier)
    input_data = b'\x0A\x14\x1E' # 10, 20, 30

    result = sandbox.run(input_data)

    assert isinstance(result.execution_time_ns, int)
    assert result.execution_time_ns > 0

    # Input:  [10, 20, 30]
    # Reversed: [30, 20, 10]
    # Add 0 (default modifier):  [30, 20, 10]
    expected_output = b'\x1E\x14\x0A' # 30, 20, 10
    assert result.output == expected_output
